import { ChangeDetectorRef, Component, EventEmitter, Input, OnChanges, OnInit, Output, SimpleChanges } from '@angular/core';
import { IconComponent } from "../../../icon/icon.component";
import { CommonModule } from '@angular/common';
import { TranslateModule } from '@ngx-translate/core';
import { filterItemType, issueFilterType, issueItem, markNavjFilters, navFilterTab } from '../../../../interfaces/mark-nav-filter.interface';
import { NgSelectModule } from '@ng-select/ng-select';
import { FormsModule } from '@angular/forms';
import { ButtonComponent } from "../../../button/button.component";
import { MatCheckboxModule } from '@angular/material/checkbox';
import { IssueService } from '../../../../../rt/services/issue/issue.service';
import { CommonService } from '../../../../services/common/common.service';
import { codeData } from '../../../../interfaces/common.interface';


@Component({
  selector: 'issues',
  standalone: true,
  imports: [CommonModule, TranslateModule, IconComponent, NgSelectModule, FormsModule, ButtonComponent, MatCheckboxModule],
  templateUrl: './issues.component.html',
  styleUrl: './issues.component.scss'
})
export class IssuesComponent implements OnChanges, OnInit {
  ngDoCheck(): void {
    // Debug: Log current filter values
    console.log('[IssuesComponent] jIssues:', this.jIssues, 'jRels:', this.jRels, 'jImps:', this.jImps, 'IsNote:', this.IsNote, 'IsFactlink:', this.IsFactlink, 'IsComment:', this.IsComment);
  }

  @Input() nCaseid: string;
  @Input() nUserid: string;

  @Input() selectedFilters: filterItemType[] = [];
  @Output() onClear: EventEmitter<void> = new EventEmitter<void>();

  issueList: issueItem[] = [];
  relevance: codeData[] = [];
  impact: codeData[] = [];

  @Input() jIssues: string[] = [];
  @Output() jIssuesChange: EventEmitter<string[]> = new EventEmitter<string[]>();

  @Input() jRels: number[] = [];
  @Output() jRelsChange: EventEmitter<number[]> = new EventEmitter<number[]>();

  @Input() jImps: number[] = [];
  @Output() jImpsChange: EventEmitter<number[]> = new EventEmitter<number[]>();

  isLoading: boolean = true;



  @Input() IsNote: boolean;
  @Output() IsNoteChange: EventEmitter<boolean> = new EventEmitter<boolean>();

  @Input() IsFactlink: boolean;
  @Output() IsFactlinkChange: EventEmitter<boolean> = new EventEmitter<boolean>();

  @Input() IsComment: boolean;
  @Output() IsCommentChange: EventEmitter<boolean> = new EventEmitter<boolean>();


  selectedIssues: issueItem[] = [];
  selectedRelavance: codeData[] = [];
  selectedImpact: codeData[] = [];

  @Output() onEmitData: EventEmitter<any> = new EventEmitter<any>();

  @Input() tab: navFilterTab;


  resetSelect: any;
  constructor(private readonly issue: IssueService, private readonly common: CommonService, private readonly cdr: ChangeDetectorRef) { }


  ngOnInit(): void {
    this.initData();
  }

  ngOnChanges(changes: SimpleChanges): void {
    // Check if any input values changed after component initialization
    if (changes['jIssues'] || changes['jRels'] || changes['jImps'] || changes['IsNote'] || changes['IsFactlink'] || changes['IsComment']) {
      if (this.issueList?.length || this.relevance?.length || this.impact?.length) {
        this.updateSelectedValues();
      }
    }
  }

  updateSelectedValues() {
    // Update selected issues
    if (this.jIssues && this.jIssues.length > 0 && this.issueList?.length) {
      this.selectedIssues = this.issueList.filter(issue => this.jIssues.includes(issue.nIid));
    } else {
      this.selectedIssues = [];
    }

    // Update selected relevance
    if (this.jRels && this.jRels.length > 0 && this.relevance?.length) {
      this.selectedRelavance = this.relevance.filter(rel => this.jRels.includes(rel.nValue));
    } else {
      this.selectedRelavance = [];
    }

    // Update selected impact
    if (this.jImps && this.jImps.length > 0 && this.impact?.length) {
      this.selectedImpact = this.impact.filter(imp => this.jImps.includes(imp.nValue));
    } else {
      this.selectedImpact = [];
    }

    // Trigger change detection
    this.cdr.detectChanges();
  }


  async initData() {
    try {
      this.issueList = [];
      this.relevance = [];
      this.impact = [];
      this.issueList = await this.issue.fetchIssueList({ nCaseid: this.nCaseid, nSessionid: null, nIDid: null, nUserid: this.nUserid });
      this.relevance = await this.common.getCode(4);
      this.impact = await this.common.getCode(5);

      // Use the new updateSelectedValues method with a small delay for proper timing
      setTimeout(() => {
        this.updateSelectedValues();
      }, 0);

      this.isLoading = false;
      this.cdr.detectChanges();
    } catch (error) {
      this.isLoading = false;
      this.cdr.detectChanges();
    }
  }


  removeall(flag: filterItemType) {
    this.selectedIssues = [];
    this.selectedRelavance = [];
    this.selectedImpact = [];
    this.IsNote = false;
    this.IsFactlink = false;
    this.IsComment = false;
    const index = this.selectedFilters.indexOf(flag);
    if (index > -1) {
      this.selectedFilters.splice(index, 1);
    }
    this.emitData();
    this.onClear.emit();
  }


  isOptionDisabled(item: issueItem | codeData, flag: issueFilterType): boolean {
    if (flag == 'I') {
      return this.selectedIssues.some(selected => selected.nIid === (item as issueItem).nIid);
    }
    if (flag == 'R') {
      return this.selectedRelavance.some(selected => selected.nValue === (item as codeData).nValue);
    }
    if (flag == 'IM') {
      return this.selectedImpact.some(selected => selected.nValue === (item as codeData).nValue);
    }
    return false;
  }


  OnValueChnaged(e: any, flag: issueFilterType) {
    if (flag == 'R') {
      const idx = this.selectedRelavance.findIndex(selected => selected.nValue === e.nValue);
      if (idx == -1) {
        this.selectedRelavance.push(e);
      }
    }
    if (flag == 'IM') {
      const idx = this.selectedImpact.findIndex(selected => selected.nValue === e.nValue);
      if (idx == -1) {
        this.selectedImpact.push(e);
      }
    }

    if (flag == 'I') {
      const idx = this.selectedIssues.findIndex(selected => selected.nIid === e.nIid);
      if (idx == -1) {
        this.selectedIssues.push(e);
      }
    }
    this.emitData();
    setTimeout(() => {
      this.resetSelect = null;
    }, 10);
  }

  remove(index: number, flag: issueFilterType) {
    if (flag == 'I') {
      this.selectedIssues.splice(index, 1)
    }
    if (flag == 'R') {
      this.selectedRelavance.splice(index, 1)
    }
    if (flag == 'IM') {
      this.selectedImpact.splice(index, 1)
    }
    this.emitData();
  }

  selectAllIssues() {
    if (this.selectedIssues.length == this.issueList.length) {
      this.selectedIssues = [];
    } else {
      this.selectedIssues = this.issueList;
    }
    this.emitData();
  }

  handleChange() {
    this.emitData();
  }

  emitData() {
    this.jIssues = this.selectedIssues.map(item => item.nIid);
    this.jRels = this.selectedRelavance.map(item => item.nValue);
    this.jImps = this.selectedImpact.map(item => item.nValue);
    this.jIssuesChange.emit(this.jIssues);
    this.jRelsChange.emit(this.jRels);
    this.jImpsChange.emit(this.jImps);
    this.IsNoteChange.emit(this.IsNote);
    this.IsFactlinkChange.emit(this.IsFactlink);
    this.IsCommentChange.emit(this.IsComment);
    this.onEmitData.emit();
  }

  trackByIndex(index: number): number {
    return index;
  }
}
