import { ChangeDetectorRef, Component, EventEmitter, Input, OnChanges, OnInit, Output, SimpleChanges } from '@angular/core';
import { CommonModule } from '@angular/common';
import { NgSelectModule } from '@ng-select/ng-select';
import { TranslateModule } from '@ngx-translate/core';
import { IconComponent } from "../../../icon/icon.component";
import { ButtonComponent } from "../../../button/button.component";
import { IssueService } from '../../../../../rt/services/issue/issue.service';
import { claimItem, filterItemType } from '../../../../interfaces/mark-nav-filter.interface';
import { FormsModule } from '@angular/forms';

@Component({
  selector: 'claims',
  standalone: true,
  imports: [CommonModule, NgSelectModule, IconComponent, ButtonComponent, FormsModule, TranslateModule],
  templateUrl: './claims.component.html',
  styleUrl: './claims.component.scss'
})
export class ClaimsComponent implements OnInit, OnChanges {

  @Input() nCaseid: string;
  @Input() nUserid: string;

  @Input() selectedFilters: filterItemType[] = [];

  @Input() jClaims: string[] = [];
  @Output() jClaimsChange: EventEmitter<string[]> = new EventEmitter<string[]>();
  @Output() onClear: EventEmitter<void> = new EventEmitter<void>();

  claimList: claimItem[] = [];
  selectedClaims: claimItem[] = [];
  resetSelect: any;

  constructor(private readonly issue: IssueService, private readonly cdr: ChangeDetectorRef) { }

  ngOnInit(): void {
    void this.loadClaimList();
  }

  private async loadClaimList(): Promise<void> {
    this.claimList = await this.issue.getCategory(this.nCaseid, this.nUserid);
    // Always update selected claims after claimList is loaded
    setTimeout(() => this.updateSelectedClaims(), 0);
  }

  ngOnChanges(changes: SimpleChanges): void {
    if (changes['jClaims']) {
      // If claimList is already loaded, update immediately
      if (this.claimList?.length) {
        this.updateSelectedClaims();
      }
      // If claimList is not loaded yet, updateSelectedClaims will be called in ngOnInit
    }
  }

  updateSelectedClaims() {
    if (this.jClaims && this.jClaims.length > 0 && this.claimList?.length) {
      this.selectedClaims = this.claimList.filter(item => this.jClaims.includes(item.nICid));
    } else {
      this.selectedClaims = [];
    }
    // Trigger change detection to ensure UI updates
    this.cdr.detectChanges();
  }

  isOptionDisabled(item: any): boolean {
    return this.selectedClaims.some(selected => selected.nICid === item.nICid);
  }

  removeFilter(flag: filterItemType) {
    this.selectedClaims = [];
    const index = this.selectedFilters.indexOf(flag);
    if (index > -1) {
      this.selectedFilters.splice(index, 1);
    }
    this.emitData();
    this.onClear.emit();
  }

  OnValueChnaged(e: claimItem) {
    const idx = this.selectedClaims.findIndex(selected => selected.nICid === e.nICid);
    if (idx === -1) {
      this.selectedClaims.push(e);
      this.emitData();
    }
    setTimeout(() => {
      this.resetSelect = null;
    }, 10);
  }

  remove(index: number) {
    this.selectedClaims.splice(index, 1)
    this.emitData();
  }

  trackByIndex(_index: number, item: claimItem): string | number {
    return item?.nICid ?? _index;
  }

  emitData() {
    this.jClaims = this.selectedClaims.map(item => item.nICid);
    this.jClaimsChange.emit(this.jClaims);
  }
}
