import { Component, EventEmitter, Input, Output, ChangeDetectorRef, Directive } from '@angular/core';
import { filterItemType } from '../../../interfaces/mark-nav-filter.interface';

/**
 * Abstract Base Class for Navigation Filters.
 *
 * @description
 * Shared logic for sidebar/navigation filters (Claims, Tasks, Facts, etc.).
 * Provides standard inputs like `nCaseid`, `nUserid` and output `onClear`.
 */
@Directive()
export abstract class BaseNavFilterComponent {

    /** Case Identifier */
    @Input() nCaseid: string = '';

    /** User Identifier */
    @Input() nUserid: string = '';

    /** List of actively selected filter types (for UI state) */
    @Input() selectedFilters: filterItemType[] = [];

    /** Emits when the filter is cleared/removed */
    @Output() readonly onClear = new EventEmitter<void>();

    constructor(protected cdr: ChangeDetectorRef) { }

    /**
     * Helper to mark for check (OnPush)
     */
    protected markForCheck(): void {
        this.cdr.markForCheck();
    }

    /**
     * Abstract method to ensure implementing classes define data emission logic.
     */
    abstract emitData(): void;
}
