import { ChangeDetectionStrategy, ChangeDetectorRef, Component, EventEmitter, Input, OnChanges, OnInit, Output, SimpleChanges } from '@angular/core';
import { MatRadioModule } from '@angular/material/radio';
import { MatSelectModule } from '@angular/material/select';
import { CommonModule } from '@angular/common';
import { IconComponent } from '../../../icon/icon.component';
import { FormsModule } from '@angular/forms';
import { ButtonComponent } from '../../../button/button.component';
import { NgSelectModule } from '@ng-select/ng-select';
import { ContactselectComponent } from '../../../contactselect/contactselect.component';
import { AvatarComponent } from '../../../avatar/avatar.component';
import { MatCheckboxModule } from '@angular/material/checkbox';
import { CommonService } from '../../../../services/common/common.service';
import { companyItem, filterItemType, userRoleItem } from '../../../../interfaces/mark-nav-filter.interface';
import { ContactService } from '../../../../services/contact/contact.service';
import { codeData } from '../../../../interfaces/common.interface';
import { selectedContactList } from '../../../../../marking/interfaces/fact.interface';
import { BaseNavFilterComponent } from '../../base/base-nav-filter.component';
import { TranslateModule } from '@ngx-translate/core';

@Component({
  selector: 'factcontactfilter',
  standalone: true,
  imports: [
    CommonModule,
    MatRadioModule,
    MatSelectModule,
    IconComponent,
    FormsModule,
    ButtonComponent,
    NgSelectModule,
    ContactselectComponent,
    AvatarComponent,
    MatCheckboxModule,
    TranslateModule
  ],
  templateUrl: './factcontactfilter.component.html',
  styleUrl: './factcontactfilter.component.scss',
  changeDetection: ChangeDetectionStrategy.OnPush
})
export class FactcontactfilterComponent extends BaseNavFilterComponent implements OnInit, OnChanges {

  @Input() contactFilter: any = {};
  @Input() jContacts: string[] = [];
  @Output() jContactsChange = new EventEmitter<string[]>();

  @Input() jCRoles: string[] = [];
  @Output() jCRolesChange = new EventEmitter<string[]>();

  @Input() jCPartys: number[] = [];
  @Output() jCPartysChange = new EventEmitter<number[]>();

  @Input() jCCompanies: string[] = [];
  @Output() jCCompaniesChange = new EventEmitter<string[]>();

  @Input() IsContactNote: boolean = false;
  @Output() IsContactNoteChange = new EventEmitter<boolean>();

  @Output() onEmitData = new EventEmitter<void>();

  role_list: userRoleItem[] = [];
  party_list: codeData[] = [];
  company_list: companyItem[] = [];
  contactList: selectedContactList[] = [];

  selectedroles: userRoleItem[] = [];
  selectedContact: selectedContactList[] = [];
  selectedParties: codeData[] = [];
  selectedCompanies: companyItem[] = [];

  resetSelect: string | null = null;

  constructor(
    protected override cdr: ChangeDetectorRef,
    private readonly common: CommonService,
    private readonly contactService: ContactService
  ) {
    super(cdr);
  }

  ngOnInit() {
    this.initData();
  }

  ngOnChanges(changes: SimpleChanges): void {
    // Check if any input values changed after component initialization
    if (changes['jContacts'] || changes['jCRoles'] || changes['jCPartys'] || changes['jCCompanies']) {
      if (this.contactList?.length || this.role_list?.length || this.party_list?.length || this.company_list?.length) {
        this.updateSelectedValues();
      }
    }
  }

  updateSelectedValues() {
    // Update selected contacts
    if (this.jContacts && this.jContacts.length > 0 && this.contactList?.length) {
      this.selectedContact = this.contactList.filter(contact => this.jContacts.includes(contact.nContactid));
    } else {
      this.selectedContact = [];
    }

    // Update selected roles
    if (this.jCRoles && this.jCRoles.length > 0 && this.role_list?.length) {
      this.selectedroles = this.role_list.filter(role => this.jCRoles.includes(role.nCRoleid));
    } else {
      this.selectedroles = [];
    }

    // Update selected parties
    if (this.jCPartys && this.jCPartys.length > 0 && this.party_list?.length) {
      this.selectedParties = this.party_list.filter(party => this.jCPartys.includes(party.nValue));
    } else {
      this.selectedParties = [];
    }

    // Update selected companies
    if (this.jCCompanies && this.jCCompanies.length > 0 && this.company_list?.length) {
      this.selectedCompanies = this.company_list.filter(company => this.jCCompanies.includes(company.nCompanyid));
    } else {
      this.selectedCompanies = [];
    }

    this.markForCheck();
  }

  async initData() {
    try {
      // Parallelize requests for performance
      const [roleList, partyList, companyList] = await Promise.all([
        this.contactService.getContactCaserolelist(this.nCaseid),
        this.common.getCode(22),
        this.contactService.getContactCompany(this.nCaseid)
      ]);

      this.role_list = roleList;
      this.party_list = partyList;
      this.company_list = companyList;

      console.log('party list', this.role_list);

      this.contactList = await this.contactService.getContactList(this.nCaseid, this.contactFilter);

      // setTimeout to ensure change detection picks up after async
      setTimeout(() => {
        this.updateSelectedValues();
      }, 0);
    } catch (error) {
      console.error('Error initializing fact contact filter data', error);
    }
  }

  OnValueChnaged(e: userRoleItem | companyItem | codeData, flag: 'R' | 'P' | 'C') {
    const isDisabled = this.isOptionDisabled(e, flag);
    if (isDisabled) {
      return;
    }

    if (flag === 'R') {
      const role = e as userRoleItem;
      const idx = this.selectedroles.findIndex(selected => selected.nCRoleid === role.nCRoleid);
      if (idx === -1) {
        this.selectedroles.push(role);
      }
    }

    if (flag === 'P') {
      const party = e as codeData;
      const idx = this.selectedParties.findIndex(selected => selected.nValue === party.nValue);
      if (idx === -1) {
        this.selectedParties.push(party);
      }
    }

    if (flag === 'C') {
      const company = e as companyItem;
      const idx = this.selectedCompanies.findIndex(selected => selected.nCompanyid === company.nCompanyid);
      if (idx === -1) {
        this.selectedCompanies.push(company);
      }
    }

    this.emitData();
    setTimeout(() => {
      this.resetSelect = null;
      this.markForCheck();
    }, 10);
  }

  isOptionDisabled(item: userRoleItem | companyItem | codeData, flag: 'R' | 'P' | 'C'): boolean {
    if (flag === 'R') {
      return this.selectedroles.some(selected => selected.nCRoleid === (item as userRoleItem).nCRoleid);
    }
    if (flag === 'P') {
      return this.selectedParties.some(selected => selected.nValue === (item as codeData).nValue);
    }
    if (flag === 'C') {
      return this.selectedCompanies.some(selected => selected.nCompanyid === (item as companyItem).nCompanyid);
    }
    return false;
  }

  onActiveContactsChange(user: selectedContactList) {
    const idx = this.selectedContact.findIndex(selected => selected.nContactid === user.nContactid);
    if (idx === -1) {
      this.selectedContact.push(user);
      this.emitData();
    }
  }

  remove(index: number, flag: 'R' | 'O' | 'C' | 'CN') {
    if (flag === 'R') {
      this.selectedroles.splice(index, 1);
    } else if (flag === 'O') {
      this.selectedParties.splice(index, 1);
    } else if (flag === 'C') {
      this.selectedCompanies.splice(index, 1); // fixed logic (was separate ifs, else if is cleaner)
    } else if (flag === 'CN') {
      this.selectedContact.splice(index, 1);
    }

    this.emitData();
  }

  trackByIndex(_index: number, item: any): string | number {
    return item?.nContactid ?? item?.nCRoleid ?? item?.nValue ?? item?.nCompanyid ?? _index;
  }

  handleChange() {
    this.emitData();
  }

  removeFilter(flag: string) { // flag is likely string 'C', cast to filterItemType if needed
    // The template passes 'C'. The Base expects filterItemType (which includes 'C').
    // Use proper casting
    this.selectedContact = [];
    this.selectedroles = [];
    this.selectedParties = [];
    this.selectedCompanies = [];
    this.IsContactNote = false;

    // Remove from selectedFilters if present
    const index = this.selectedFilters.indexOf(flag as filterItemType);
    if (index > -1) {
      this.selectedFilters.splice(index, 1);
    }

    this.emitData();
    this.onClear.emit();
  }

  emitData(): void {
    this.jContacts = this.selectedContact.map(selected => selected.nContactid);
    this.jCRoles = this.selectedroles.map(selected => selected.nCRoleid);
    this.jCPartys = this.selectedParties.map(selected => selected.nValue);
    this.jCCompanies = this.selectedCompanies.map(selected => selected.nCompanyid);

    this.jContactsChange.emit(this.jContacts);
    this.jCRolesChange.emit(this.jCRoles);
    this.jCPartysChange.emit(this.jCPartys);
    this.jCCompaniesChange.emit(this.jCCompanies);
    this.IsContactNoteChange.emit(this.IsContactNote);

    this.onEmitData.emit();
    this.markForCheck();
  }
}
