import { ChangeDetectionStrategy, ChangeDetectorRef, Component, EventEmitter, Input, OnChanges, Output, SimpleChanges } from '@angular/core';
import { MatRadioModule } from '@angular/material/radio';
import { MatSelectModule } from '@angular/material/select';
import { CommonModule } from '@angular/common';
import { MatCheckboxModule } from '@angular/material/checkbox';
import { FormsModule } from '@angular/forms';
import { NgSelectModule } from '@ng-select/ng-select';

import { IconComponent } from '../../../icon/icon.component';
import { ButtonComponent } from '../../../button/button.component';
import { DatepickerComponent } from '../../../datepicker/datepicker.component';
import { ContactselectComponent } from '../../../contactselect/contactselect.component';
import { AvatarComponent } from '../../../avatar/avatar.component';
import { DateFormComponent, jDateType } from "../../../../../marking/components/fact/date-form/date-form.component";
import { TeamSelectComponent } from "../../../team-select/team-select.component";
import { CommonService } from '../../../../services/common/common.service';
import { codeData } from '../../../../interfaces/common.interface';
import { myTeamUsers } from '../../../../../marking/interfaces/teamshare.interface';
import { filterItemType, QFACT_DATE_TYPE } from '../../../../interfaces/mark-nav-filter.interface';
import { TranslateModule } from '@ngx-translate/core';

@Component({
  selector: 'factdetailfilter',
  standalone: true,
  changeDetection: ChangeDetectionStrategy.OnPush,
  imports: [
    CommonModule,
    MatRadioModule,
    MatSelectModule,
    IconComponent,
    FormsModule,
    ButtonComponent,
    DatepickerComponent,
    NgSelectModule,
    ContactselectComponent,
    AvatarComponent,
    DateFormComponent,
    TranslateModule,
    TeamSelectComponent,
    MatCheckboxModule
  ],
  templateUrl: './factdetailfilter.component.html',
  styleUrl: './factdetailfilter.component.scss'
})
export class FactdetailfilterComponent implements OnChanges {

  @Input() isIndividual: boolean = false;

  // Inputs/outputs previously supplied by BaseNavFilterComponent
  @Input() nCaseid: string;
  @Input() nUserid: string;
  @Input() selectedFilters: filterItemType[] = [];
  @Output() onClear: EventEmitter<void> = new EventEmitter<void>();

  @Input() jFilters: any;
  @Output() readonly jFiltersChange = new EventEmitter<number[]>(); // Helper type mismatch in original? Emitting 'jFilters'? Kept strict to original usage but fixed generic if needed.

  @Input() jLevels: any;
  @Output() readonly jLevelsChange = new EventEmitter<any>();

  private initialized = false;

  isFileLevel: boolean = false;
  isPageLevel: boolean = false;

  qfactdatetype = QFACT_DATE_TYPE;


  selecteddatetype: any = 1;
  resetSelect: any;
  filetypeList: codeData[] = [];
  statusList: codeData[] = [];

  @Input() jDate: jDateType = {} as jDateType;
  @Output() readonly jDateChange = new EventEmitter<jDateType>();

  selectedType: codeData[] = [];
  selectedStatus: codeData[] = [];
  selectedContact: myTeamUsers[] = [];
  userList: myTeamUsers[] = [];

  @Input() jFiletypes: number[] = [];
  @Output() readonly jFiletypesChange = new EventEmitter<number[]>();

  @Input() jStatus: number[] = [];
  @Output() readonly jStatusChange = new EventEmitter<number[]>();

  @Input() createDate: { start: string, end: string } | null = null;
  @Output() readonly createDateChange = new EventEmitter<{ start: string, end: string } | null>();

  @Input() createBy: string[] = [];
  @Output() readonly createByChange = new EventEmitter<string[]>();

  @Output() readonly onEmitData = new EventEmitter<any>();

  constructor(
    private common: CommonService,
    private cdr: ChangeDetectorRef
  ) {
  }

  ngOnInit() {
    this.initData();

    if (this.jFilters && Object.keys(this.jFilters).length > 0) {
      if (this.jFilters.hasOwnProperty('cType')) {
        this.isFileLevel = true;
        this.isPageLevel = false;
      }
    } else {
      this.isFileLevel = false;
      this.isPageLevel = true;
    }
  }

  ngOnChanges(changes: SimpleChanges): void {
    if (changes['jFiletypes'] || changes['jStatus'] || changes['createBy'] || changes['createDate'] || changes['jLevels']) {
      if (this.filetypeList?.length || this.statusList?.length || this.userList?.length) {
        this.updateSelectedValues();
      }
    }
  }

  updateSelectedValues() {
    // Update selected file types
    if (this.jFiletypes?.length && this.filetypeList?.length) {
      this.selectedType = this.filetypeList.filter(item => this.jFiletypes.includes(item.nValue));
    } else {
      this.selectedType = [];
    }

    // Update selected status
    if (this.jStatus?.length && this.statusList?.length) {
      this.selectedStatus = this.statusList.filter(item => this.jStatus.includes(item.nValue));
    } else {
      this.selectedStatus = [];
    }

    // Update selected contact
    if (this.createBy?.length && this.userList?.length) {
      this.selectedContact = this.userList.filter(user => this.createBy.includes(user.nUserid));
    } else {
      this.selectedContact = [];
    }

    // Update levels
    if (this.jLevels) {
      if (this.jLevels === 'M') {
        this.isFileLevel = true;
        this.isPageLevel = false;
      } else if (this.jLevels === 'S') {
        this.isFileLevel = false;
        this.isPageLevel = true;
      }
    } else {
      this.isFileLevel = false;
      this.isPageLevel = true;
    }

    this.cdr.markForCheck();
  }

  async initData() {
    this.statusList = await this.common.getCode(24);
    this.filetypeList = await this.common.getCode(23);
    this.userList = await this.common.getMyTeamUsers(this.nCaseid);
    this.userList = this.userList.filter(user => user.nUserid != this.nUserid);

    // Initial sync
    setTimeout(() => {
      this.updateSelectedValues();
      this.initialized = true;
    }, 0);

    if (this.jFilters) {
      if (this.jFilters.hasOwnProperty('selecteddatetype')) {
        this.selecteddatetype = this.jFilters.selecteddatetype;
      }
    } else {
      this.jFilters = {};
    }
    this.cdr.markForCheck();
  }

  handleLevel(e: any) {
    if (!e.checked) {
      e.source.checked = true;
      return;
    }
    if (e.source.name === 'fileLevel') {
      this.isFileLevel = e.checked;
      this.isPageLevel = !e.checked;
    } else {
      this.isPageLevel = e.checked;
      this.isFileLevel = !e.checked;
    }
    this.emitData();
  }

  OnValueChnaged(e: codeData, flag: 'T' | 'S') {
    const isdisabled = this.isOptionDisabled(e, flag);
    if (isdisabled) return;

    if (flag === 'T') {
      const idx = this.selectedType.findIndex(selected => selected.nValue === e.nValue);
      if (idx === -1) this.selectedType.push(e);
    }

    if (flag === 'S') {
      const idx = this.selectedStatus.findIndex(selected => selected.nValue === e.nValue);
      if (idx === -1) this.selectedStatus.push(e);
    }

    this.emitData();
    setTimeout(() => {
      this.resetSelect = null;
      this.cdr.markForCheck();
    }, 10);
  }

  onActiveContactsChange(user: myTeamUsers) {
    const idx = this.selectedContact.findIndex(selected => selected.nUserid === user.nUserid);
    if (idx == -1) {
      this.selectedContact.push(user);
      this.emitData();
    }
  }

  onRemoveContact(user: myTeamUsers) {
    const idx = this.selectedContact.findIndex(selected => selected.nUserid === user.nUserid);
    if (idx != -1) {
      this.selectedContact.splice(idx, 1);
      this.emitData();
    }
  }

  OnDateChange(e: jDateType) {
    if (e?.record?.length > 0) {
      this.jDate = e;
      this.jDateChange.emit(e);
    } else {
      this.jDate = null;
      this.jDateChange.emit(null);
    }
  }

  isOptionDisabled(item: codeData, flag: 'T' | 'S'): boolean {
    if (flag === 'T') {
      return this.selectedType.some(selected => selected.nValue === item.nValue);
    }
    if (flag === 'S') {
      return this.selectedStatus.some(selected => selected.nValue === item.nValue);
    }
    return false;
  }

  handleDateChange(e: any) {
    if (this.selecteddatetype == 1) {
      this.createDate = { start: e, end: e };
    } else {
      const [start, end] = e;
      if (!start || !end) return;
      this.createDate = { start: start, end: end };
    }
    if (this.initialized) {
      this.emitData();
    } else {
      this.createDateChange.emit(this.createDate);
    }
  }

  removeFilter(flag: filterItemType) {
    this.selectedType = [];
    this.selectedStatus = [];
    this.selectedContact = [];
    this.createDate = null;
    const index = this.selectedFilters.indexOf(flag);
    if (index > -1) {
      this.selectedFilters.splice(index, 1);
    }
    this.emitData();
    this.onClear.emit();
  }

  emitData() {
    this.jFiletypes = this.selectedType.map(selected => selected.nValue);
    this.jStatus = this.selectedStatus.map(selected => selected.nValue);
    this.createBy = this.selectedContact.map(selected => selected.nUserid);
    this.jLevels = this.isFileLevel ? 'M' : 'S';

    this.jLevelsChange.emit(this.jLevels);
    this.jFiletypesChange.emit(this.jFiletypes);
    this.jFiltersChange.emit(this.jFilters);
    this.jStatusChange.emit(this.jStatus);
    this.createDateChange.emit(this.createDate);
    this.createByChange.emit(this.createBy);
    this.onEmitData.emit();
  }

  remove(index: number, flag: 'T' | 'S') {
    if (flag === 'T') this.selectedType.splice(index, 1);
    if (flag === 'S') this.selectedStatus.splice(index, 1);
    this.emitData();
  }

  trackByIndex(_index: number, item: any): string | number {
    return item?.nValue ?? item?.nUserid ?? item?.nCompanyid ?? _index;
  }
}

