import { ChangeDetectionStrategy, ChangeDetectorRef, Component, EventEmitter, Input, OnChanges, OnInit, Output, SimpleChanges } from '@angular/core';
import { CommonModule } from '@angular/common';
import { MatRadioModule } from '@angular/material/radio';
import { MatSelectModule } from '@angular/material/select';
import { FormsModule } from '@angular/forms';
import { NgSelectModule } from '@ng-select/ng-select';
import { MatCheckboxModule } from '@angular/material/checkbox';
import { MatButtonModule } from '@angular/material/button';
import { MatDatepickerInputEvent, MatDatepickerModule } from '@angular/material/datepicker';
import { MatInputModule } from '@angular/material/input';
import { MatFormFieldModule } from '@angular/material/form-field';
import { provideNativeDateAdapter } from '@angular/material/core';
import { TranslateModule } from '@ngx-translate/core';

import { IconComponent } from '../../../icon/icon.component';
import { ButtonComponent } from '../../../button/button.component';
import { DatepickerComponent } from '../../../datepicker/datepicker.component';
import { filterItemType } from '../../../../interfaces/mark-nav-filter.interface';
import { CommonService } from '../../../../services/common/common.service';
import { TaskService } from '../../../../services/task/task.service';
import { selectedTaskItem } from '../../../../../marking/interfaces/fact.interface';
import { myTeamUsers } from '../../../../../marking/interfaces/teamshare.interface';
import { codeData } from '../../../../interfaces/common.interface';
import { BaseNavFilterComponent } from '../../base/base-nav-filter.component';

@Component({
  selector: 'facttaskfilter',
  standalone: true,
  changeDetection: ChangeDetectionStrategy.OnPush,
  imports: [
    MatRadioModule,
    MatSelectModule,
    CommonModule,
    TranslateModule,
    IconComponent,
    FormsModule,
    ButtonComponent,
    NgSelectModule,
    MatCheckboxModule,
    MatFormFieldModule,
    MatInputModule,
    MatDatepickerModule,
    MatButtonModule,
    DatepickerComponent
  ],
  templateUrl: './facttaskfilter.component.html',
  styleUrl: './facttaskfilter.component.scss',
  providers: [provideNativeDateAdapter()],
})
export class FacttaskfilterComponent extends BaseNavFilterComponent implements OnChanges {

  assigneelist: { nValue: string, cKey: string }[] = [
    { nValue: 'john_doe', cKey: 'John Doe' },
    { nValue: 'jane_smith', cKey: 'Jane Smith' },
    { nValue: 'alice_jones', cKey: 'Alice Jones' },
    { nValue: 'bob_brown', cKey: 'Bob Brown' }
  ];

  selectedassignee: myTeamUsers[] = [];
  selectedstatus: codeData[] = [];
  selectedpriority: codeData[] = [];
  taskList: selectedTaskItem[] = [];
  activeTaskItem: selectedTaskItem | undefined;
  selectedTaskList: selectedTaskItem[] = [];
  userList: myTeamUsers[] = [];
  statuslist: codeData[] = [];
  prioritylist: codeData[] = [];
  selectedDate: Date | null = null;
  resetSelect: any;

  @Input() jTasks: string[] = [];
  @Output() readonly jTasksChange = new EventEmitter<string[]>();

  @Input() IsTaskDesc: boolean = false;
  @Output() readonly IsTaskDescChange = new EventEmitter<boolean>();

  @Input() jTShared: string[] = [];
  @Output() readonly jTSharedChange = new EventEmitter<string[]>();

  @Input() jTStatus: number[] = [];
  @Output() readonly jTStatusChange = new EventEmitter<number[]>();

  @Input() jTPriority: number[] = [];
  @Output() readonly jTPriorityChange = new EventEmitter<number[]>();

  @Input() dTDate: string = '';
  @Output() readonly dTDateChange = new EventEmitter<string>();

  @Output() readonly onEmitData = new EventEmitter<any>();

  constructor(
    private readonly common: CommonService,
    private readonly taskS: TaskService,
    cdr: ChangeDetectorRef
  ) {
    super(cdr);
  }

  ngOnInit(): void {
    this.initData();
  }

  ngOnChanges(changes: SimpleChanges): void {
    // Check if any input values changed after component initialization
    if (changes['jTasks'] || changes['jTShared'] || changes['jTStatus'] || changes['jTPriority'] || changes['dTDate']) {
      if (this.taskList?.length || this.userList?.length || this.statuslist?.length || this.prioritylist?.length) {
        this.updateSelectedValues();
      }
    }
  }

  updateSelectedValues() {
    // Update selected tasks
    if (this.jTasks?.length && this.taskList?.length) {
      this.selectedTaskList = this.taskList.filter(task => this.jTasks.includes(task.nTaskid));
    } else {
      this.selectedTaskList = [];
    }

    // Update selected assignees
    if (this.jTShared?.length && this.userList?.length) {
      this.selectedassignee = this.userList.filter(user => this.jTShared.includes(user.nUserid));
    } else {
      this.selectedassignee = [];
    }

    // Update selected status
    if (this.jTStatus?.length && this.statuslist?.length) {
      this.selectedstatus = this.statuslist.filter(status => this.jTStatus.includes(status.nValue));
    } else {
      this.selectedstatus = [];
    }

    // Update selected priority
    if (this.jTPriority?.length && this.prioritylist?.length) {
      this.selectedpriority = this.prioritylist.filter(priority => this.jTPriority.includes(priority.nValue));
    } else {
      this.selectedpriority = [];
    }

    // Update selected date
    this.selectedDate = this.dTDate ? new Date(this.dTDate) : null;

    // Update task description flag
    this.IsTaskDesc = !!this.IsTaskDesc;

    this.markForCheck();
  }

  async initData() {
    const res: any = await this.taskS.getTaskList(this.nCaseid, 'FT');
    this.userList = await this.common.getMyTeamUsers(this.nCaseid);
    this.prioritylist = await this.common.getCode(17);
    this.statuslist = await this.common.getCode(25);

    if (res?.length) {
      this.taskList = res[0];
    }

    if (this.userList?.length) {
      this.userList = this.userList.filter(user => user.nUserid != this.nUserid);
    }

    // Use the new updateSelectedValues method with a small delay for proper timing
    setTimeout(() => {
      this.updateSelectedValues();
    }, 0);
  }

  OnValueChnaged(e: any, flag: 'T' | 'A' | 'P' | 'S') {
    const isdisabled = this.isOptionDisabled(e, flag);
    if (isdisabled) {
      return;
    }

    if (flag === 'A') {
      const idx = this.selectedassignee.findIndex(a => a.nUserid == e.nUserid);
      if (idx === -1) this.selectedassignee.push(e);
    }

    if (flag === 'S') {
      const idx = this.selectedstatus.findIndex(a => a.nValue == e.nValue);
      if (idx === -1) this.selectedstatus.push(e);
    }

    if (flag === 'P') {
      const idx = this.selectedpriority.findIndex(a => a.nValue == e.nValue);
      if (idx === -1) this.selectedpriority.push(e);
    }

    if (flag === 'T') {
      const idx = this.selectedTaskList.findIndex(a => a.nTaskid == e.value.nTaskid);
      if (idx === -1) this.selectedTaskList.push(e.value);
    }

    this.emitData();
    setTimeout(() => {
      this.resetSelect = null;
      this.markForCheck();
    }, 10);
  }

  isOptionDisabled(item: myTeamUsers | codeData | selectedTaskItem, flag: 'A' | 'S' | 'P' | 'T'): boolean {
    if (flag === 'A') {
      return this.selectedassignee.some(selected => selected.nUserid === (item as myTeamUsers).nUserid);
    }
    if (flag === 'S') {
      return this.selectedstatus.some(selected => selected.nValue === (item as codeData).nValue);
    }
    if (flag === 'P') {
      return this.selectedpriority.some(selected => selected.nValue === (item as codeData).nValue);
    }
    if (flag === 'T') {
      return this.selectedTaskList.some(selected => selected.nTaskid === (item as selectedTaskItem).nTaskid);
    }
    return false;
  }

  remove(index: number, flag: 'T' | 'A' | 'P' | 'S') {
    if (flag === 'A') this.selectedassignee.splice(index, 1);
    if (flag === 'S') this.selectedstatus.splice(index, 1);
    if (flag === 'P') this.selectedpriority.splice(index, 1);
    if (flag === 'T') this.selectedTaskList.splice(index, 1);
    this.emitData();
  }

  onDateChange(event: MatDatepickerInputEvent<Date>) {
    this.emitData();
  }

  handleChange() {
    this.emitData();
  }

  removeFilter(flag: filterItemType) {
    this.selectedTaskList = [];
    this.selectedassignee = [];
    this.selectedstatus = [];
    this.selectedpriority = [];
    this.selectedDate = null;
    this.IsTaskDesc = false;

    const index = this.selectedFilters.indexOf(flag);
    if (index > -1) {
      this.selectedFilters.splice(index, 1);
    }
    this.emitData();
    this.onClear.emit();
  }

  emitData() {
    this.jTasks = this.selectedTaskList.map(selected => selected.nTaskid);
    this.jTShared = this.selectedassignee.map(selected => selected.nUserid);
    this.jTStatus = this.selectedstatus.map(selected => selected.nValue);
    this.jTPriority = this.selectedpriority.map(selected => selected.nValue);
    // this.dTDate = this.selectedDate ? this.selectedDate.toISOString().split('T')[0] : '';
    // Original code assigned Date object to selectedDate, and emitted it.
    // The input dTDate is string.
    // Let's keep strict type:
    this.dTDate = this.selectedDate ? this.selectedDate.toString() : ''; // Or helper to format YYYY-MM-DD if needed.
    // Reverting to original logic: this.selectedDate was assigned to dTDate directly?
    // "this.dTDate = this.selectedDate;" in original line 275.
    // If selectedDate is Date object (line 134), and dTDate is string (line 82), that's an issue in original code too?
    // Wait, onDateChange (line 241) updates selectedDate via binding probably?
    // line 275: "this.dTDate = this.selectedDate;"
    // I'll assume standard string handling or JS loose typing. I'll cast to any if needed or use toString().
    // Actually, MatDatepicker uses Date.

    this.jTasksChange.emit(this.jTasks);
    this.jTSharedChange.emit(this.jTShared);
    this.jTStatusChange.emit(this.jTStatus);
    this.jTPriorityChange.emit(this.jTPriority);
    this.dTDateChange.emit(this.dTDate as any); // Type assertion to match original potentially loose behavior or fix it.
    this.IsTaskDescChange.emit(this.IsTaskDesc);
    this.onEmitData.emit();
  }

  trackByIndex(index: number): number {
    return index;
  }
}

